PREFIXED = {i for i in range(1, 21)}
RESULTS = {}

def label(n):
    s = STEPS[n - 1]
    return ("Verify this works end to end: " + s) if n in PREFIXED else s

def record(n, status, comment):
    RESULTS[n] = {"step": label(n), "status": status, "comment": comment[:600]}
    out = [RESULTS[i] for i in sorted(RESULTS)]
    tmp = os.path.join(SHOTS, ".live-results.tmp")
    with open(tmp, "w") as f:
        json.dump({"testResults": out}, f, indent=1)
    os.replace(tmp, os.path.join(SHOTS, "live-results.json"))
    print("[%02d] %s — %s" % (n, status.upper(), comment[:160]))

