def set_range(elem_id, target, limit=220):
    """Drive a native range input to an exact value with the arrow keys.

    Pressing a fixed number of arrows is not repeatable — the saved placement from
    the previous run is the starting point — so walk to the target and assert it."""
    wait_sel("#" + elem_id)
    J("document.getElementById(%r).focus()" % elem_id)
    for _ in range(limit):
        v = int(float(J("document.getElementById(%r).value" % elem_id)))
        if v == target:
            break
        press_key("ArrowRight" if v < target else "ArrowLeft")
    time.sleep(0.8)
    return int(float(J("document.getElementById(%r).value" % elem_id)))

def fill(selector, value):
    T()
    wait_sel(selector)
    J("(()=>{const e=document.querySelector(%r); e.focus(); e.select && e.select();})()" % selector)
    type_text(str(value))

def set_select(selector, matcher):
    return J("""(()=>{const s=document.querySelector(%r); if(!s) return null;
      const o=[...s.options].find(o=>o.text.includes(%r)||o.value===%r); if(!o) return null;
      s.value=o.value; s.dispatchEvent(new Event('change',{bubbles:true})); return o.value;})()"""
             % (selector, matcher, matcher))

def artwork_png(path, w=900, h=900, pad=150):
    """Square orange mark on a transparent border — passes the transparency check."""
    def chunk(t, d):
        c = t + d
        return struct.pack(">I", len(d)) + c + struct.pack(">I", zlib.crc32(c))
    rows = []
    for y in range(h):
        row = bytearray(b"\x00")
        for x in range(w):
            inside = pad <= x < w - pad and pad <= y < h - pad
            row += bytes([255, 90, 0, 255] if inside else [0, 0, 0, 0])
        rows.append(bytes(row))
    png = (b"\x89PNG\r\n\x1a\n"
           + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
           + chunk(b"IDAT", zlib.compress(b"".join(rows)))
           + chunk(b"IEND", b""))
    with open(path, "wb") as f:
        f.write(png)
    return path

