# ================================================ 12. Gemini suggestions
try:
    G(NORTHWIND + "/assistant")

    def pending_count():
        m = re.search(r"Pending review (\d+)", text())
        return int(m.group(1)) if m else 0

    before = pending_count()
    ok = J("""(()=>{const f=[...document.querySelectorAll('form')].find(f=>f.innerText.includes('Draft description and'));
        if(!f) return false; const s=f.querySelector('select[name=productId]');
        s.value=s.options[1].value; s.dispatchEvent(new Event('change',{bubbles:true}));
        f.querySelector('button[type=submit]').click(); return true;})()""")
    # A live model call is slow and its timestamps are relative, so the queue
    # length is what proves a new suggestion was drafted.
    generated = False
    deadline = time.time() + 180
    while time.time() < deadline:
        time.sleep(8)
        G(NORTHWIND + "/assistant", 0.5)
        if pending_count() > before:
            generated = True
            break
    t = text()
    pending = pending_count()
    needs_confirm = "Suggestions stay pending until you apply one" in t
    # apply one explicitly
    click_text("button", "Apply this change")
    time.sleep(6); wait_for_load()
    after = pending
    for _ in range(6):
        G(NORTHWIND + "/assistant", 0.6)
        after_m = re.search(r"Pending review (\d+)", text())
        after = int(after_m.group(1)) if after_m else pending
        if after < pending:
            break
        time.sleep(2)
    shot(12)
    record(12, "pass" if (generated and needs_confirm and after < pending) else "fail",
           "Gemini drafted a fresh description/tag suggestion (%s); suggestions are held in a pending queue that states nothing is written until applied (%s); clicking 'Apply this change' was required and dropped the pending count %d→%d"
           % (generated, needs_confirm, pending, after))
except Exception:
    record(12, "fail", "AI assistant failed: %s" % traceback.format_exc().strip().splitlines()[-1])

